def list_tools(**_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0557000" if __import__("os").path.isdir("./environment_mix/0557000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Ambient auth: if there exists any active key, allow. If no keys exist at all, allow (local/dev).
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if api_keys and not active_keys:
        # Keys exist but none active -> no working identity.
        # Log as error with api_key_id null.
        logs = _load("request_logs.json")
        log_id = "rlog_" + uuid.uuid4().hex
        duration_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": log_id,
            "api_key_id": None,
            "tool_name": "list_tools",
            "job_id": None,
            "status": "error",
            "http_status": 401,
            "error_message": "No active API key available to authorize request.",
            "duration_ms": duration_ms,
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "No active API key available to authorize request.")

    # Prepare static metadata only.
    tools = [
        {
            "name": "list_tools",
            "description": "Lists the OCR service tools/endpoints available from this server and returns their names and basic signatures; results are not paginated.",
            "parameters": {}
        },
        {
            "name": "process_local_file",
            "description": "Creates an OCR job for a document located under the configured OCR_DIR, validates the relative path, runs OCR, persists extracted text plus processing metadata, and returns the created job record including the requested result_format output.",
            "parameters": {
                "local_rel_path": "string (required)",
                "original_filename": "string (optional)",
                "result_format": "plain_text|markdown|json (optional, default plain_text)",
                "language_hint": "string (optional)"
            }
        },
        {
            "name": "process_url_file",
            "description": "Creates an OCR job for a remote document URL, fetches and validates the document, runs OCR, persists extracted text plus processing metadata, and returns the created job record including the requested result_format output.",
            "parameters": {
                "url": "string (required)",
                "original_filename": "string (optional)",
                "result_format": "plain_text|markdown|json (optional, default plain_text)",
                "language_hint": "string (optional)"
            }
        },
        {
            "name": "get_current_identity",
            "description": "Returns information about the authenticated caller, including the resolved API key identity (if any), granted scopes, and current quota/rate-limit consumption.",
            "parameters": {
                "api_key": "string (required)",
                "include_quota": "boolean (optional, default true)"
            }
        }
    ]

    # Log request (must always write a request_logs row for list_tools).
    logs = _load("request_logs.json")
    log_id = "rlog_" + uuid.uuid4().hex
    duration_ms = int((time.time() - t0) * 1000)
    logs.append({
        "id": log_id,
        "api_key_id": None,
        "tool_name": "list_tools",
        "job_id": None,
        "status": "ok",
        "http_status": 200,
        "error_message": None,
        "duration_ms": duration_ms,
        "created_at": now,
        "updated_at": now
    })
    _save("request_logs.json", logs)

    return {"tools": tools}

def process_url_file(url, original_filename=None, result_format=None, language_hint=None, **_extra):
    import json, os, datetime, time, uuid, hashlib, mimetypes
    import urllib.parse, urllib.request

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0557000" if __import__("os").path.isdir("./environment_mix/0557000") else "/app/database")
    MAX_BYTES = int(os.environ.get("MOCR_MAX_INPUT_BYTES") or (10 * 1024 * 1024))
    FETCH_TIMEOUT = float(os.environ.get("MOCR_FETCH_TIMEOUT_S") or "10")
    SUPPORTED_CT = {
        "application/pdf",
        "image/png",
        "image/jpeg",
        "image/jpg",
        "image/tiff",
        "image/tif",
        "image/webp",
        "image/bmp",
    }

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{uuid.uuid4().hex[:16]}"

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _append_request_log(tool_name, api_key_id, job_id, status, http_status=None, error_message=None, t0=None):
        logs = _load("request_logs.json")
        now = _now_iso()
        duration_ms = None
        if t0 is not None:
            try:
                duration_ms = int((time.time() - t0) * 1000)
                if duration_ms < 0:
                    duration_ms = 0
            except Exception:
                duration_ms = None
        logs.append(
            {
                "id": _gen_id("mocr_req"),
                "api_key_id": api_key_id,
                "tool_name": tool_name,
                "job_id": job_id,
                "status": status,
                "http_status": http_status,
                "error_message": error_message,
                "duration_ms": duration_ms,
                "created_at": now,
                "updated_at": now,
            }
        )
        _save("request_logs.json", logs)

    def _resolve_ambient_api_key_id_for_processing():
        keys = _load("api_keys.json")
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active" and k.get("id")]
        if active:
            return active[0]["id"]
        return None

    t0 = time.time()

    # Validate inputs
    if not isinstance(url, str) or not url.strip():
        _append_request_log("process_url_file", None, None, "error", 400, "url is required.", t0)
        return _err("VALIDATION_ERROR", "url is required.", field="url")
    url = url.strip()

    if original_filename is not None and not isinstance(original_filename, str):
        _append_request_log("process_url_file", None, None, "error", 400, "original_filename must be a string.", t0)
        return _err("VALIDATION_ERROR", "original_filename must be a string.", field="original_filename")

    if language_hint is not None and not isinstance(language_hint, str):
        _append_request_log("process_url_file", None, None, "error", 400, "language_hint must be a string.", t0)
        return _err("VALIDATION_ERROR", "language_hint must be a string.", field="language_hint")

    if result_format is None:
        result_format = "plain_text"
    if not isinstance(result_format, str) or result_format not in ("plain_text", "markdown", "json"):
        _append_request_log("process_url_file", None, None, "error", 400, "result_format must be one of: plain_text, markdown, json.", t0)
        return _err("VALIDATION_ERROR", "result_format must be one of: plain_text, markdown, json.", field="result_format")

    # Validate and normalize URL
    try:
        parsed = urllib.parse.urlsplit(url)
    except Exception:
        _append_request_log("process_url_file", None, None, "error", 400, "Invalid URL.", t0)
        return _err("VALIDATION_ERROR", "Invalid URL.", field="url")
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        _append_request_log("process_url_file", None, None, "error", 400, "URL must be http or https with a host.", t0)
        return _err("VALIDATION_ERROR", "URL must be http or https with a host (business rule: http/https only).", field="url")
    # Normalize: lower scheme/host; preserve path/query; drop fragment
    netloc = parsed.netloc.lower()
    norm_url = urllib.parse.urlunsplit((parsed.scheme.lower(), netloc, parsed.path or "/", parsed.query or "", ""))

    # Create job row now
    now = _now_iso()
    api_key_id = _resolve_ambient_api_key_id_for_processing()
    job_id = _gen_id("mocr_job")
    jobs = _load("ocr_jobs.json")
    derived_name = os.path.basename(parsed.path) or None
    job = {
        "id": job_id,
        "api_key_id": api_key_id,
        "source_type": "url",
        "local_rel_path": None,
        "url": norm_url,
        "original_filename": (original_filename.strip() if isinstance(original_filename, str) and original_filename.strip() else derived_name),
        "content_type": None,
        "input_bytes": None,
        "sha256": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "processor": "mistral_ocr",
        "processor_version": "2025.07.1",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)
    _save("ocr_jobs.json", jobs)

    # Attempt lightweight HEAD/GET fetch to determine content-type/size; if offline/unreachable, proceed using historical cached metadata for same URL
    content_type = None
    file_bytes = None
    sha256 = None

    def _set_job_status(new_status, **fields):
        jrows = _load("ocr_jobs.json")
        for j in jrows:
            if isinstance(j, dict) and j.get("id") == job_id:
                cur = j.get("status")
                allowed = {
                    "queued": {"fetching", "processing", "cancelled", "failed"},
                    "fetching": {"processing", "failed", "cancelled"},
                    "processing": {"succeeded", "failed", "cancelled"},
                    "succeeded": set(),
                    "failed": set(),
                    "cancelled": set(),
                }
                if cur in ("succeeded", "failed", "cancelled"):
                    break
                if new_status != cur and new_status not in allowed.get(cur, set()):
                    return False
                j["status"] = new_status
                for k, v in fields.items():
                    j[k] = v
                j["updated_at"] = _now_iso()
                if new_status in ("failed", "succeeded", "cancelled") and not j.get("finished_at"):
                    j["finished_at"] = j["updated_at"]
                if new_status in ("processing",) and not j.get("started_at"):
                    j["started_at"] = j["updated_at"]
                break
        _save("ocr_jobs.json", jrows)
        return True

    _set_job_status("fetching", started_at=_now_iso())

    fetch_error = None
    fetched_bytes = b""
    headers_ct = None
    headers_len = None

    try:
        req = urllib.request.Request(norm_url, method="GET", headers={"User-Agent": "mocr-offline/1.0"})
        with urllib.request.urlopen(req, timeout=FETCH_TIMEOUT) as resp:
            headers_ct = resp.headers.get("Content-Type")
            headers_len = resp.headers.get("Content-Length")
            if headers_len is not None:
                try:
                    headers_len = int(headers_len)
                except Exception:
                    headers_len = None
            if headers_len is not None and headers_len > MAX_BYTES:
                fetch_error = ("file_too_large", f"Input exceeds configured maximum size ({MAX_BYTES // (1024*1024)} MB).")
            else:
                # Read up to MAX_BYTES+1 to enforce limit
                chunk_size = 1024 * 1024
                while True:
                    chunk = resp.read(chunk_size)
                    if not chunk:
                        break
                    fetched_bytes += chunk
                    if len(fetched_bytes) > MAX_BYTES:
                        fetch_error = ("file_too_large", f"Input exceeds configured maximum size ({MAX_BYTES // (1024*1024)} MB).")
                        break
    except Exception as e:
        fetch_error = ("fetch_failed", f"Remote resource could not be retrieved: {type(e).__name__}.")

    if fetch_error is None:
        file_bytes = len(fetched_bytes)
        # Normalize content-type (strip charset)
        if headers_ct:
            content_type = headers_ct.split(";")[0].strip().lower()
        if not content_type:
            # Guess from URL path
            ct_guess, _enc = mimetypes.guess_type(parsed.path)
            content_type = ct_guess.lower() if isinstance(ct_guess, str) else None
        # Hash
        sha256 = hashlib.sha256(fetched_bytes).hexdigest()

    if fetch_error is not None:
        # Try cache from previous jobs for same URL
        existing_jobs = _load("ocr_jobs.json")
        cached = None
        for j in existing_jobs:
            if isinstance(j, dict) and j.get("source_type") == "url" and j.get("url") == norm_url:
                if j.get("sha256") and isinstance(j.get("input_bytes"), int):
                    cached = j
                    break
        if cached:
            content_type = cached.get("content_type")
            file_bytes = cached.get("input_bytes")
            sha256 = cached.get("sha256")
            fetch_error = None

    if fetch_error is not None:
        code, msg = fetch_error
        _set_job_status("failed", error_code=code, error_message=msg, content_type=content_type, input_bytes=file_bytes, sha256=sha256)
        http_status = 404 if code == "fetch_failed" else 413
        api_code = "NOT_FOUND" if code == "fetch_failed" else "QUOTA_EXCEEDED"
        _append_request_log("process_url_file", api_key_id, job_id, "error", http_status, msg, t0)
        return _err(api_code, msg, error_code=code, job_id=job_id)

    # Now enforce supported type
    if content_type is not None and content_type not in SUPPORTED_CT:
        msg = f"Unsupported content type: {content_type}. Only PDF and common image formats are allowed."
        _set_job_status("failed", error_code="unsupported_type", error_message=msg, content_type=content_type, input_bytes=int(file_bytes) if isinstance(file_bytes, int) else None, sha256=sha256)
        _append_request_log("process_url_file", api_key_id, job_id, "error", 415, msg, t0)
        return _err("VALIDATION_ERROR", "Unsupported content type (business rule: only PDF/images may proceed).", error_code="unsupported_type", job_id=job_id, content_type=content_type)

    # Enforce size (cached path too)
    if isinstance(file_bytes, int) and file_bytes > MAX_BYTES:
        msg = f"Input exceeds configured maximum size ({MAX_BYTES // (1024*1024)} MB)."
        _set_job_status("failed", error_code="file_too_large", error_message=msg, content_type=content_type, input_bytes=int(file_bytes), sha256=sha256)
        _append_request_log("process_url_file", api_key_id, job_id, "error", 413, msg, t0)
        return _err("QUOTA_EXCEEDED", "Input exceeds maximum size (business rule: max input_bytes).", error_code="file_too_large", job_id=job_id)

    # Move to processing and store metadata
    _set_job_status("processing", content_type=content_type, input_bytes=int(file_bytes), sha256=sha256)

    # Create stored_files and output; enforce unique constraints similarly to local path
    stored = _load("stored_files.json")
    if any(isinstance(s, dict) and s.get("sha256") == sha256 and s.get("bytes") == int(file_bytes) for s in stored):
        msg = "Deduplication conflict: stored object already exists with same sha256 and bytes, but schema requires uniqueness; cannot create per-job stored_files row."
        _set_job_status("failed", error_code="ocr_failed", error_message=msg)
        _append_request_log("process_url_file", api_key_id, job_id, "error", 409, "Deduplication conflict.", t0)
        return _err("CONFLICT", "Deduplication conflict with unique(sha256, bytes) constraint (cannot create stored_files row for this job).", error_code="ocr_failed", job_id=job_id)

    stored_id = _gen_id("mocr_file")
    stored_row = {
        "id": stored_id,
        "job_id": job_id,
        "storage_backend": "object_store",
        "storage_path": f"object://mocr/{job_id}",
        "content_type": content_type,
        "bytes": int(file_bytes),
        "sha256": sha256,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    stored.append(stored_row)
    _save("stored_files.json", stored)

    outputs = _load("ocr_outputs.json")
    out = None
    if any(isinstance(o, dict) and o.get("job_id") == job_id for o in outputs):
        out = next(o for o in outputs if isinstance(o, dict) and o.get("job_id") == job_id)
    else:
        text = None
        structured = None
        if result_format == "json":
            structured = {
                "partial": False,
                "note": "Offline simulated OCR output. Real engine output not available in this environment.",
                "language_hint": language_hint,
                "url": norm_url,
            }
        else:
            name = job.get("original_filename") or (os.path.basename(parsed.path) or "document")
            base = f"OCR output for {name}"
            if language_hint:
                base += f" (language_hint={language_hint})"
            text = base + "\n"
        out = {
            "id": _gen_id("mocr_out"),
            "job_id": job_id,
            "result_format": result_format,
            "language_hint": language_hint,
            "page_count": None,
            "text": text,
            "structured": structured,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        outputs.append(out)
        _save("ocr_outputs.json", outputs)

    # Mark job succeeded
    _set_job_status("succeeded")
    # Fix timestamp ordering if needed
    jobs = _load("ocr_jobs.json")
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            qa = _parse_iso(j.get("queued_at"))
            sa = _parse_iso(j.get("started_at"))
            fa = _parse_iso(j.get("finished_at"))
            if qa and sa and sa < qa:
                j["started_at"] = j["queued_at"]
            if qa and fa and fa < qa:
                j["finished_at"] = j["queued_at"]
            j["updated_at"] = j.get("finished_at") or j["updated_at"]
            break
    _save("ocr_jobs.json", jobs)

    if api_key_id is not None:
        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("id") == api_key_id and k.get("status") == "active":
                k["last_used_at"] = _now_iso()
                k["updated_at"] = k["last_used_at"]
                break
        _save("api_keys.json", keys)

    _append_request_log("process_url_file", api_key_id, job_id, "ok", 200, None, t0)

    jobs = _load("ocr_jobs.json")
    job_row = next((j for j in jobs if isinstance(j, dict) and j.get("id") == job_id), job)
    outputs = _load("ocr_outputs.json")
    out_row = next((o for o in outputs if isinstance(o, dict) and o.get("job_id") == job_id), None)
    stored = _load("stored_files.json")
    stored_row2 = next((s for s in stored if isinstance(s, dict) and s.get("job_id") == job_id), None)
    return {
        "job": job_row,
        "output": out_row,
        "stored_file": stored_row2,
    }

def get_current_identity(api_key, include_quota=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0557000" if __import__("os").path.isdir("./environment_mix/0557000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # NOTE: request_logs schema enum doesn't include this tool_name; cannot log without breaking constraints.
    # Service dynamics for this endpoint are therefore limited to updating api_keys.last_used_at on success.

    if include_quota is None:
        include_quota = True

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required.")
    if not isinstance(include_quota, bool):
        return _err("VALIDATION_ERROR", "include_quota must be a boolean.")

    keys = _load("api_keys.json")
    # Authenticate by matching client-visible value or id; only id exists in schema.
    key_row = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key:
            key_row = k
            break

    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid credentials.")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked.")

    # Update last_used_at
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    updated = False
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            k["last_used_at"] = ts
            k["updated_at"] = ts
            updated = True
            key_row = k
            break
    if updated:
        _save("api_keys.json", keys)

    identity = {
        "api_key": {
            "id": key_row.get("id"),
            "name": key_row.get("name"),
            "status": key_row.get("status"),
            "created_at": key_row.get("created_at"),
            "last_used_at": key_row.get("last_used_at"),
        },
        "scopes": ["ocr:read", "ocr:write", "identity:read"]
    }

    if include_quota:
        # No explicit quota schema; provide observable counters from request_logs as "usage".
        logs = _load("request_logs.json")
        # Count calls in last 60s and last 24h for this api_key_id
        now_dt = datetime.datetime.utcnow()
        def _parse_z(s):
            if not isinstance(s, str) or not s.endswith("Z"):
                return None
            try:
                return datetime.datetime.fromisoformat(s[:-1])
            except Exception:
                return None

        last_60 = 0
        last_24h = 0
        total = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_row.get("id"):
                continue
            total += 1
            tsr = _parse_z(r.get("created_at"))
            if tsr is None:
                continue
            if (now_dt - tsr).total_seconds() <= 60:
                last_60 += 1
            if (now_dt - tsr).total_seconds() <= 86400:
                last_24h += 1

        identity["quota"] = {
            "observed_usage": {
                "requests_last_60s": last_60,
                "requests_last_24h": last_24h,
                "requests_total_logged": total
            },
            "limits": None
        }

    identity["request_duration_ms"] = int((time.time() - t0) * 1000)
    return identity

def list_ocr_jobs(api_key, status=None, source_type=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0557000" if __import__("os").path.isdir("./environment_mix/0557000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time_ns()) + prefix).encode('utf-8')).hexdigest()[:24]}"

    def _log_request(api_key_id, tool_name, job_id, status_s, http_status, error_message, started_monotonic):
        logs = _load("request_logs.json")
        dur = int(max(0, (time.monotonic() - started_monotonic) * 1000))
        now = _now_iso()
        row = {
            "id": _gen_id("rlog"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "job_id": job_id,
            "status": status_s,
            "http_status": http_status,
            "error_message": error_message,
            "duration_ms": dur,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.monotonic()
    api_key_id = None
    try:
        # Validate inputs
        if api_key is None or not isinstance(api_key, str) or not api_key.strip():
            _log_request(None, "list_tools", None, "error", 401, "Missing or invalid api_key.", t0)
            return _err("UNAUTHORIZED", "Missing or invalid api_key.")

        if status is not None:
            if not isinstance(status, str) or status not in ["queued", "fetching", "processing", "succeeded", "failed", "cancelled"]:
                _log_request(None, "list_tools", None, "error", 400, "Invalid status filter.", t0)
                return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")

        if source_type is not None:
            if not isinstance(source_type, str) or source_type not in ["local_file", "url"]:
                _log_request(None, "list_tools", None, "error", 400, "Invalid source_type filter.", t0)
                return _err("VALIDATION_ERROR", "Invalid source_type filter.", field="source_type")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log_request(None, "list_tools", None, "error", 400, "Invalid limit.", t0)
            return _err("VALIDATION_ERROR", "Invalid limit.", field="limit", minimum=1, maximum=200)

        if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
            _log_request(None, "list_tools", None, "error", 400, "Invalid cursor.", t0)
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

        ca = _parse_rfc3339(created_after)
        if created_after is not None and ca is None:
            _log_request(None, "list_tools", None, "error", 400, "Invalid created_after timestamp.", t0)
            return _err("VALIDATION_ERROR", "Invalid created_after timestamp.", field="created_after")

        cb = _parse_rfc3339(created_before)
        if created_before is not None and cb is None:
            _log_request(None, "list_tools", None, "error", 400, "Invalid created_before timestamp.", t0)
            return _err("VALIDATION_ERROR", "Invalid created_before timestamp.", field="created_before")

        if ca is not None and cb is not None and cb < ca:
            _log_request(None, "list_tools", None, "error", 400, "created_before must be >= created_after.", t0)
            return _err("VALIDATION_ERROR", "created_before must be >= created_after.", field="created_before")

        # Authenticate: match against id OR key_hash (client-visible value)
        keys = _load("api_keys.json")
        key_row = None
        ak = api_key.strip()
        for r in keys:
            if isinstance(r, dict) and (r.get("id") == ak or r.get("key_hash") == ak):
                key_row = r
                break
        if key_row is None:
            _log_request(None, "list_tools", None, "error", 401, "Invalid api_key.", t0)
            return _err("UNAUTHORIZED", "Invalid api_key.")

        api_key_id = key_row.get("id")
        if key_row.get("status") != "active":
            _log_request(api_key_id, "list_tools", None, "error", 403, "API key is revoked.", t0)
            return _err("UNAUTHORIZED", "API key is revoked.")

        # Pagination cursor decoding: base64url(json: {"offset": int})
        offset = 0
        if cursor:
            try:
                padded = cursor + "=" * (-len(cursor) % 4)
                raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
                obj = json.loads(raw)
                if not isinstance(obj, dict) or not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                    _log_request(api_key_id, "list_tools", None, "error", 400, "Invalid cursor.", t0)
                    return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
                offset = obj["offset"]
            except Exception:
                _log_request(api_key_id, "list_tools", None, "error", 400, "Invalid cursor.", t0)
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

        jobs = _load("ocr_jobs.json")

        # Filter: only jobs submitted with this api_key_id (visibility)
        filtered = []
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("api_key_id") != api_key_id:
                continue
            if status is not None and j.get("status") != status:
                continue
            if source_type is not None and j.get("source_type") != source_type:
                continue
            if ca is not None:
                jt = _parse_rfc3339(j.get("created_at"))
                if jt is None or jt < ca:
                    continue
            if cb is not None:
                jt = _parse_rfc3339(j.get("created_at"))
                if jt is None or jt >= cb:
                    continue
            filtered.append(j)

        # Sort newest first by created_at then id
        def _sort_key(j):
            dt = _parse_rfc3339(j.get("created_at"))
            if dt is None:
                dt = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            return (dt, j.get("id") or "")
        filtered.sort(key=_sort_key, reverse=True)

        total = len(filtered)
        page = filtered[offset: offset + limit]
        has_more = offset + limit < total
        next_cursor = None
        if has_more:
            payload = json.dumps({"offset": offset + limit}, separators=(",", ":")).encode("utf-8")
            next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

        # Update last_used_at for successful call
        now = _now_iso()
        changed = False
        for r in keys:
            if isinstance(r, dict) and r.get("id") == api_key_id:
                r["last_used_at"] = now
                r["updated_at"] = now
                changed = True
                break
        if changed:
            _save("api_keys.json", keys)

        # Log call (note: request_logs schema tool_name enum doesn't include these tools; do not write invalid rows)
        # Observable dynamics are enforced where schema allows; these tools are not listed in request_logs.tool_name enum.
        # Return response
        return {
            "data": page,
            "meta": {
                "total": total,
                "limit": limit,
                "has_more": has_more,
                "next_cursor": next_cursor
            }
        }
    except Exception as e:
        # Unexpected server error: return structured error object (do not raise)
        try:
            return _err("CONFLICT", "Internal error.", detail=str(e))
        except Exception:
            return {"error": {"code": "CONFLICT", "message": "Internal error."}}

