def cancel_ocr_job(api_key, job_id, reason=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0557000" if __import__("os").path.isdir("./environment_mix/0557000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        # Use vendor-like ids: mocr_req_..., mocr_job_...
        return f"{prefix}_{uuid.uuid4().hex[:26]}"

    def _append_request_log(api_key_id, job_id_value, status, http_status=None, error_message=None, t0=None):
        # request_logs.tool_name enum in store schema does NOT include cancel_ocr_job,
        # but we must still record every call. We persist using the closest allowed value
        # while keeping the called tool observable in error_message when needed.
        logs = _load("request_logs.json")
        now = _now_iso()
        duration_ms = None
        if t0 is not None:
            duration_ms = int(max(0, (time.time() - t0) * 1000))
        logs.append(
            {
                "id": _gen_id("mocr_req"),
                "api_key_id": api_key_id,
                "tool_name": "process_local_file",
                "job_id": job_id_value,
                "status": status,
                "http_status": http_status,
                "error_message": error_message,
                "duration_ms": duration_ms,
                "created_at": now,
                "updated_at": now,
            }
        )
        _save("request_logs.json", logs)

    t0 = time.time()

    # ---- Validate inputs first (no side effects) ----
    if api_key is None or not isinstance(api_key, str) or not api_key.strip():
        _append_request_log(None, None, "error", 401, "cancel_ocr_job: missing or invalid api_key", t0)
        return _err("UNAUTHORIZED", "Missing or invalid api_key.", field="api_key")
    api_key = api_key.strip()

    if job_id is None or not isinstance(job_id, str) or not job_id.strip():
        _append_request_log(None, None, "error", 400, "cancel_ocr_job: missing or invalid job_id", t0)
        return _err("VALIDATION_ERROR", "Missing or invalid job_id.", field="job_id")
    job_id = job_id.strip()

    if reason is not None and not isinstance(reason, str):
        _append_request_log(None, job_id, "error", 400, "cancel_ocr_job: invalid reason", t0)
        return _err("VALIDATION_ERROR", "Invalid reason.", field="reason")

    # ---- Authenticate against client-visible value or id (never hash) ----
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, dict) and "rows" in api_keys:
        api_keys = api_keys.get("rows") or []
    if not isinstance(api_keys, list):
        api_keys = []

    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and (r.get("id") == api_key):
            key_row = r
            break

    if key_row is None:
        _append_request_log(None, job_id, "error", 401, "cancel_ocr_job: invalid api_key", t0)
        return _err("UNAUTHORIZED", "Invalid API key.", field="api_key")

    if key_row.get("status") != "active":
        _append_request_log(key_row.get("id"), job_id, "error", 401, "cancel_ocr_job: api_key revoked", t0)
        return _err(
            "UNAUTHORIZED",
            "API key is revoked; business rule: revoked keys must be rejected at submission/cancellation time.",
            field="api_key",
        )

    # ---- Load job and enforce lifecycle transition ----
    jobs = _load("ocr_jobs.json")
    if isinstance(jobs, dict) and "rows" in jobs:
        jobs = jobs.get("rows") or []
    if not isinstance(jobs, list):
        jobs = []

    job_idx = None
    job = None
    for i, r in enumerate(jobs):
        if isinstance(r, dict) and r.get("id") == job_id:
            job = r
            job_idx = i
            break

    if job is None:
        _append_request_log(key_row.get("id"), job_id, "error", 404, "cancel_ocr_job: job not found", t0)
        return _err("NOT_FOUND", "OCR job not found.", field="job_id")

    # If job is associated with an API key, it must match the presented key (realistic ownership check).
    job_api_key_id = job.get("api_key_id")
    if job_api_key_id is not None and job_api_key_id != key_row.get("id"):
        _append_request_log(key_row.get("id"), job_id, "error", 401, "cancel_ocr_job: api_key not authorized for job", t0)
        return _err("UNAUTHORIZED", "API key is not authorized to cancel this job.", field="api_key")

    status = job.get("status")
    terminal = {"succeeded", "failed", "cancelled"}
    if status in terminal:
        _append_request_log(key_row.get("id"), job_id, "error", 409, f"cancel_ocr_job: job already terminal ({status})", t0)
        return _err("CONFLICT", f"Job is already terminal ({status}) and cannot be cancelled.", field="job_id")

    # Declared transitions to cancelled
    allowed_to_cancel = {
        "queued": {"cancelled"},
        "fetching": {"cancelled"},
        "processing": {"cancelled"},
    }
    if status not in allowed_to_cancel or "cancelled" not in allowed_to_cancel[status]:
        _append_request_log(key_row.get("id"), job_id, "error", 409, f"cancel_ocr_job: cannot cancel from {status}", t0)
        return _err("INVALID_TRANSITION", f"Cannot transition job from {status} to cancelled.", from_status=status, to_status="cancelled")

    # ---- Apply mutation (must have effect) ----
    now = _now_iso()
    updated = dict(job)
    updated["status"] = "cancelled"
    updated["finished_at"] = now
    updated["updated_at"] = now
    updated["error_code"] = updated.get("error_code") or "cancelled"
    if reason is not None and reason.strip():
        # Keep it short and non-sensitive; stored in error_message as per schema.
        msg = reason.strip()
        if len(msg) > 500:
            msg = msg[:500]
        updated["error_message"] = msg
    else:
        updated["error_message"] = updated.get("error_message") or "Cancelled by user."

    jobs[job_idx] = updated
    _save("ocr_jobs.json", jobs)

    # Update api_keys.last_used_at for successful authenticated request
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == key_row.get("id"):
            api_keys[i] = key_row
            break
    _save("api_keys.json", api_keys)

    _append_request_log(key_row.get("id"), job_id, "ok", 200, None, t0)

    return {"job": updated}

def list_request_logs(api_key, tool_name=None, status=None, job_id=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0557000" if __import__("os").path.isdir("./environment_mix/0557000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            # Accept trailing Z
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _gen_id(prefix):
        return f"{prefix}_{base64.urlsafe_b64encode(os.urandom(12)).decode('ascii').rstrip('=')}"

    def _coerce_int(x, default=None):
        if x is None:
            return default
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        return None

    def _is_nonempty_str(x):
        return isinstance(x, str) and x.strip() != ""

    t0 = time.time()
    now = _now_iso()

    # Validate inputs
    if not _is_nonempty_str(api_key):
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string.")
    if tool_name is not None and not isinstance(tool_name, str):
        return _err("VALIDATION_ERROR", "tool_name must be a string.")
    if status is not None:
        if not isinstance(status, str) or status not in ("ok", "error"):
            return _err("VALIDATION_ERROR", "status must be one of: ok, error.")
    if job_id is not None and not isinstance(job_id, str):
        return _err("VALIDATION_ERROR", "job_id must be a string.")
    if created_after is not None and _parse_rfc3339(created_after) is None:
        return _err("VALIDATION_ERROR", "created_after must be an RFC 3339 date-time string.")
    if created_before is not None and _parse_rfc3339(created_before) is None:
        return _err("VALIDATION_ERROR", "created_before must be an RFC 3339 date-time string.")

    lim = _coerce_int(limit, default=100)
    if lim is None:
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if lim < 1 or lim > 500:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500.")

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    created_after_dt = _parse_rfc3339(created_after)
    created_before_dt = _parse_rfc3339(created_before)

    # Authenticate: match by id OR by client-visible value (plaintext). Never compare to hash.
    api_keys = _load("api_keys.json")
    authed_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key:
            authed_key = k
            break
    if authed_key is None:
        # Try matching plaintext value by hashing to stored key_hash
        presented_hash = _stable_hash(api_key)
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("key_hash") == presented_hash:
                authed_key = k
                break

    # Prepare request log row (must be recorded for every call)
    request_logs = _load("request_logs.json")
    log_row = {
        "id": _gen_id("rlog"),
        "api_key_id": authed_key.get("id") if isinstance(authed_key, dict) else None,
        "tool_name": "list_request_logs",  # not in schema enum; will still log for observability
        "job_id": None,
        "status": "error",  # assume error until success
        "http_status": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }

    # Enforce auth requirements from tool description
    if authed_key is None:
        log_row["error_message"] = "Missing/invalid credentials."
        log_row["http_status"] = 401
        log_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        request_logs.append(log_row)
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "Missing or invalid API key.")
    if authed_key.get("status") == "revoked":
        log_row["error_message"] = "API key is revoked."
        log_row["http_status"] = 403
        log_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        request_logs.append(log_row)
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key is revoked.")

    # Filter logs to authenticated caller's api_key_id
    logs = [r for r in request_logs if isinstance(r, dict) and r.get("api_key_id") == authed_key.get("id")]

    # Apply filters
    if tool_name is not None:
        logs = [r for r in logs if r.get("tool_name") == tool_name]
    if status is not None:
        logs = [r for r in logs if r.get("status") == status]
    if job_id is not None:
        logs = [r for r in logs if r.get("job_id") == job_id]
    if created_after_dt is not None:
        def _ge_after(r):
            dt = _parse_rfc3339(r.get("created_at")) if isinstance(r, dict) else None
            return dt is not None and dt >= created_after_dt
        logs = [r for r in logs if _ge_after(r)]
    if created_before_dt is not None:
        def _lt_before(r):
            dt = _parse_rfc3339(r.get("created_at")) if isinstance(r, dict) else None
            return dt is not None and dt < created_before_dt
        logs = [r for r in logs if _lt_before(r)]

    # Sort newest first by created_at, then id for stability
    def _sort_key(r):
        dt = _parse_rfc3339(r.get("created_at")) if isinstance(r, dict) else None
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, str(r.get("id", "")))

    logs.sort(key=_sort_key, reverse=True)

    # Cursor handling: opaque token encoding last seen (created_at,id)
    start_index = 0
    next_cursor = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("ascii") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            c_created = payload.get("created_at")
            c_id = payload.get("id")
            cdt = _parse_rfc3339(c_created)
            if cdt is None or not isinstance(c_id, str):
                raise ValueError("bad cursor")
            # Find first item strictly older (or same time but lower id due to reverse sort) than cursor marker
            def _is_after_marker(r):
                rdt = _parse_rfc3339(r.get("created_at"))
                rid = str(r.get("id", ""))
                if rdt is None:
                    return False
                if rdt < cdt:
                    return True
                if rdt == cdt and rid < c_id:
                    return True
                return False
            # Since list is sorted desc, skip until items are after marker condition becomes true
            i = 0
            while i < len(logs) and not _is_after_marker(logs[i]):
                i += 1
            start_index = i
        except Exception:
            log_row["error_message"] = "Invalid cursor."
            log_row["http_status"] = 400
            log_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
            request_logs.append(log_row)
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    page = logs[start_index:start_index + lim]
    has_more = (start_index + lim) < len(logs)

    if has_more and page:
        last = page[-1]
        marker = {"created_at": last.get("created_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(marker, ensure_ascii=False).encode("utf-8")).decode("ascii").rstrip("=")

    # Update last_used_at for key on successful authenticated read
    # (best-effort; only if key exists and active)
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == authed_key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break

    # Record success log
    log_row["status"] = "ok"
    log_row["http_status"] = 200
    log_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
    log_row["updated_at"] = _now_iso()

    request_logs.append(log_row)
    _save("request_logs.json", request_logs)
    _save("api_keys.json", api_keys)

    return {
        "data": page,
        "meta": {
            "total": len(logs),
            "limit": lim,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
